
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b97_1p_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b97_1p", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.782958063890100e+00, -3.709649179171571e+00, -3.606974758548801e+00, -3.464859191007588e+00, -3.271483143095256e+00, -3.014800882051877e+00, -2.686208580547894e+00, -2.287549362696464e+00, -1.841640665511184e+00, -1.396562523896195e+00, -9.656923644036294e-01, -6.508917364967474e-01, -5.620104808419512e-01, -4.607930302054339e-01, -3.319476898385690e-01, -2.092290337534710e-01, -1.317636358480964e-01, -6.248243524959644e-02, -1.509843625607420e-02, -1.769447787623362e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


